-- 104_product_invoice_fields.sql
-- Invoice fields on planner.products for the Commercial/Tax Invoice + Packing List generator.
-- Source: SKU_CHILD-MERGE PRODUCT (1).csv (Ben, Airtable-owned going forward). 987 rows, matched by SKU.
-- sku_invoice_title = invoice description incl. fibre composition. hscode_* = HS code per destination;
-- for any country not listed (e.g. Dubai), the generator falls back to hscode_us.
-- grs_material_product (certification/recycled text) already exists on the table.
-- Idempotent: ADD COLUMN IF NOT EXISTS + UPDATE by SKU. Safe to run on live as-is.

ALTER TABLE planner.products
  ADD COLUMN IF NOT EXISTS sku_invoice_title text,
  ADD COLUMN IF NOT EXISTS hscode_uk text,
  ADD COLUMN IF NOT EXISTS hscode_us text,
  ADD COLUMN IF NOT EXISTS hscode_eu text,
  ADD COLUMN IF NOT EXISTS hscode_ca text,
  ADD COLUMN IF NOT EXISTS hscode_au text;

UPDATE planner.products p SET
  sku_invoice_title=v.title, hscode_uk=v.uk, hscode_us=v.us, hscode_eu=v.eu, hscode_ca=v.ca, hscode_au=v.au
FROM (VALUES
